'use strict';
function output(id,text){document.getElementById(id).textContent=text;}
var visits=Number(localStorage.getItem('visits')||0)+1;
localStorage.setItem('visits',visits);sessionStorage.setItem('current-view',location.pathname);
output('storage-state','Profile visits: '+visits+' · session view: '+sessionStorage.getItem('current-view'));
function showRoute(){output('route-state','Route: '+location.pathname);}
document.querySelectorAll('.route-link').forEach(function(link){link.onclick=function(event){event.preventDefault();history.pushState({route:link.getAttribute('href')},'',link.getAttribute('href'));sessionStorage.setItem('current-view',location.pathname);showRoute();};});
window.onpopstate=showRoute;showRoute();
var canvas=document.getElementById('chart');var context=canvas.getContext('2d');var rows=[];
function drawChart(){context.clearRect(0,0,760,300);context.fillStyle='#f4f8fe';context.fillRect(0,0,760,300);context.font='18px sans-serif';context.fillStyle='#25446c';context.fillText('Live data from fetch()',24,30);context.beginPath();context.moveTo(52,245);context.lineTo(710,245);context.strokeStyle='#a4bad5';context.lineWidth=2;context.stroke();rows.forEach(function(row,i){var x=70+i*155;var h=row.value*3;context.fillStyle=i%2===0?'#2475c9':'#4b9fe0';context.fillRect(x,245-h,95,h);context.fillStyle='#21324b';context.font='15px sans-serif';context.fillText(row.label,x,274);context.fillText(String(row.value),x+28,235-h);});var badge=document.getElementById('badge');if(badge.complete&&badge.naturalWidth>0)context.drawImage(badge,700,8,40,40);}
document.getElementById('badge').onload=drawChart;
var mutation=new MutationObserver(function(records){output('mutation-state','MutationObserver records: '+records.length);});mutation.observe(document.getElementById('data-root'),{childList:true,subtree:true});
var resize=new ResizeObserver(function(entries){output('resize-state','ResizeObserver width: '+Math.round(entries[0].contentRect.width));});resize.observe(document.getElementById('chart-card'));
var intersection=new IntersectionObserver(function(entries){output('intersection-state','IntersectionObserver visible: '+entries[0].isIntersecting);},{threshold:[0,0.5,1]});intersection.observe(canvas);
function loadData(){return fetch('/api/data').then(function(response){return response.json();}).then(function(data){rows=data.rows;var list=document.getElementById('data-root');list.textContent='';rows.forEach(function(row){var item=document.createElement('li');item.textContent=row.label+': '+row.value;list.appendChild(item);});output('fetch-state','Fetched '+rows.length+' JSON rows');drawChart();worker.postMessage(rows);}).catch(function(error){output('fetch-state',error.name+': '+error.message);});}
var worker=new Worker('/worker.js');worker.onmessage=function(event){output('worker-state','Worker total: '+event.data.total+' · DOM: '+event.data.dom);};worker.onerror=function(){output('worker-state','Worker error');};
var socket=new WebSocket('ws://'+location.host+'/ws');socket.onopen=function(){socket.send('hello from the page');};socket.onmessage=function(event){output('socket-state','WebSocket echo: '+event.data);socket.close();};
var events=new EventSource('/api/events');events.onmessage=function(event){output('sse-state','EventSource: '+event.data);};events.addEventListener('update',function(event){output('sse-state','EventSource update: '+event.data+' · id '+event.lastEventId);events.close();});
var database;var open=indexedDB.open('phase7-demo',1);open.onupgradeneeded=function(event){var store=event.target.result.createObjectStore('settings',{keyPath:'id'});store.createIndex('by-route','route');};open.onsuccess=function(){database=open.result;database.onversionchange=function(){database.close();};var transaction=database.transaction('settings','readwrite');transaction.objectStore('settings').put({id:'view',visits:visits,route:location.pathname});transaction.oncomplete=function(){output('idb-state','IndexedDB: saved visits '+visits);};};
function checkSession(){fetch('/api/session').then(function(response){return response.json();}).then(function(session){output('login-state',session.loggedIn?'Signed in as '+session.user:'Not signed in');output('cookie-state','document.cookie: '+(document.cookie||'(HttpOnly cookie is hidden)'));});}
document.getElementById('login-form').onsubmit=function(event){event.preventDefault();var payload={username:document.getElementById('username').value,password:document.getElementById('password').value};fetch('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}).then(function(response){return response.json();}).then(function(result){if(result.loggedIn)checkSession();else output('login-state','Login rejected');});};
document.getElementById('refresh').onclick=loadData;
document.getElementById('clipboard').onclick=function(){navigator.clipboard.writeText('Phase 7 Web API Workshop').then(function(){output('permission-state','Clipboard write approved');},function(error){output('permission-state','Clipboard: '+error.name);});};
document.getElementById('geo').onclick=function(){navigator.geolocation.getCurrentPosition(function(){output('permission-state','Local position received');},function(error){output('permission-state','Geolocation error '+error.code+': '+error.message);});};
document.getElementById('notify').onclick=function(){Notification.requestPermission().then(function(permission){output('permission-state','Notifications: '+permission);if(permission==='granted')new Notification('Phase 7 Workshop',{body:'Origin permission was explicitly granted.'});});};
document.getElementById('persist').onclick=function(){navigator.storage.persist().then(function(ok){output('permission-state','Persistent storage: '+ok);});};
document.getElementById('fullscreen').onclick=function(){document.getElementById('chart-card').requestFullscreen().then(function(){output('permission-state','Fullscreen approved; Escape exits.');},function(error){output('permission-state','Fullscreen: '+error.name);});};
document.getElementById('popup').onclick=function(){window.open('/overview');};
document.getElementById('alert').onclick=function(){var answer=prompt('A native per-window prompt','Hello');output('permission-state','Prompt result: '+answer);};
drawChart();checkSession();loadData();
